/**
 * LAXII service — persistence layer between the engine and the database.
 *
 * Responsibilities:
 *  - store generated bytes as ordinary MediaAssets (owner-scoped storage keys,
 *    served through the existing /api/media/[id]/raw boundary)
 *  - append conversation messages and output versions (parent-linked tree)
 *  - ownership-checked loading of reference images for edit operations
 *  - conversation detail assembly for the studio UI
 */

import { db } from "@/lib/db";
import { putObject, buildStorageKey } from "@/lib/storage";

import type { LaxiiReferenceImage } from "./types";
import { LaxiiError } from "./types";
import { findBannerPreset, type LaxiiBannerPreset } from "./banner-presets";

const MAX_PROMPT_LENGTH = 4000;

export class LaxiiServiceError extends Error {
  status: number;
  constructor(message: string, status = 400) {
    super(message);
    this.name = "LaxiiServiceError";
    this.status = status;
  }
}

export function cleanPrompt(raw: unknown): string {
  if (typeof raw !== "string") return "";
  const trimmed = raw.trim().slice(0, MAX_PROMPT_LENGTH);
  return trimmed;
}

/** Load user-owned media as reference images (ownership enforced). */
export async function loadOwnedMediaAsReferences(userId: string, mediaIds: string[]): Promise<LaxiiReferenceImage[]> {
  if (mediaIds.length === 0) return [];
  const assets = await db.mediaAsset.findMany({
    where: { id: { in: mediaIds }, ownerId: userId, kind: "IMAGE", status: "READY" },
  });
  if (assets.length !== mediaIds.length) {
    throw new LaxiiServiceError("One or more referenced images were not found in your library.", 404);
  }
  const { getObject } = await import("@/lib/storage");
  const refs = await Promise.all(
    assets.map(async (asset) => {
      const bytes = await getObject(asset.storagePath);
      return {
        dataUrl: `data:${asset.mime};base64,${bytes.toString("base64")}`,
        mime: asset.mime,
        label: asset.filename,
      } satisfies LaxiiReferenceImage;
    })
  );
  return refs;
}

/** Persist generated bytes as a MediaAsset and return its id + dims. */
export async function storeGeneratedMedia(
  ownerId: string,
  bytes: Buffer,
  mime: string,
  width: number,
  height: number,
  label: string
): Promise<string> {
  const ext = mime === "image/jpeg" ? "jpg" : mime === "image/webp" ? "webp" : "png";
  const storagePath = buildStorageKey(ownerId, ext);
  await putObject(storagePath, bytes, mime);
  const media = await db.mediaAsset.create({
    data: {
      ownerId,
      kind: "IMAGE",
      filename: label.slice(0, 180),
      mime,
      size: bytes.length,
      width,
      height,
      status: "READY",
      storagePath,
    },
  });
  return media.id;
}

/**
 * NOTE: turn recording now lives in `jobs.ts` — generation runs as an
 * asynchronous job (USER message + RUNNING assistant message → DONE/FAILED)
 * so long real renders never hold the HTTP request open.
 */

/** Serialized version shape shared with the studio client. */
export interface SerializedVersion {
  id: string;
  mediaId: string;
  url: string;
  width: number | null;
  height: number | null;
  isSelected: boolean;
  isFavourite: boolean;
  parentVersionId: string | null;
  operation: string | null;
  prompt: string | null;
  createdAt: string;
}

export interface SerializedMessage {
  id: string;
  role: string;
  text: string;
  operation: string | null;
  provider: string | null;
  model: string | null;
  status: string;
  error: string | null;
  meta: Record<string, unknown> | null;
  createdAt: string;
  versions: SerializedVersion[];
}

function serializeVersion(v: {
  id: string;
  mediaId: string;
  isSelected: boolean;
  isFavourite: boolean;
  parentVersionId: string | null;
  operation: string | null;
  prompt: string | null;
  width: number | null;
  height: number | null;
  createdAt: Date;
}): SerializedVersion {
  return {
    id: v.id,
    mediaId: v.mediaId,
    url: `/api/media/${v.mediaId}/raw`,
    width: v.width,
    height: v.height,
    isSelected: v.isSelected,
    isFavourite: v.isFavourite,
    parentVersionId: v.parentVersionId,
    operation: v.operation,
    prompt: v.prompt,
    createdAt: v.createdAt.toISOString(),
  };
}

/** Full conversation detail for the studio. */
export async function conversationDetail(userId: string, conversationId: string) {
  const conversation = await db.laxiiConversation.findFirst({
    where: { id: conversationId, userId },
  });
  if (!conversation) throw new LaxiiServiceError("Conversation not found.", 404);

  const messages = await db.laxiiMessage.findMany({
    where: { conversationId },
    orderBy: { createdAt: "asc" },
    include: { versions: { orderBy: { createdAt: "asc" } } },
  });

  const serialized: SerializedMessage[] = messages.map((m) => ({
    id: m.id,
    role: m.role,
    text: m.text,
    operation: m.operation,
    provider: m.provider,
    model: m.model,
    status: m.status,
    error: m.error,
    meta: m.metaJson ? (JSON.parse(m.metaJson) as Record<string, unknown>) : null,
    createdAt: m.createdAt.toISOString(),
    versions: m.versions.map(serializeVersion),
  }));

  return {
    conversation: {
      id: conversation.id,
      title: conversation.title,
      kind: conversation.kind,
      bannerKind: conversation.bannerKind,
      canvasWidth: conversation.canvasWidth,
      canvasHeight: conversation.canvasHeight,
      createdAt: conversation.createdAt.toISOString(),
      updatedAt: conversation.updatedAt.toISOString(),
    },
    messages: serialized,
  };
}

/** Validate the banner preset for banner conversations (one fixed BEAN Folio canvas). */
export function resolveBannerCanvas(presetSlug: string): { preset: LaxiiBannerPreset; width: number; height: number } {
  const preset = findBannerPreset(presetSlug);
  if (!preset) throw new LaxiiServiceError("Unknown banner preset.", 400);
  return { preset, width: preset.width, height: preset.height };
}

// ---------------------------------------------------------------------------
// Job facade — restored against the CURRENT pipeline storage
//
// A "job" is an ASSISTANT LaxiiMessage: the current pipeline
// (startGenerationJob) persists the turn, writes stage/progress into
// message metaJson and records outputs as LaxiiImageVersion rows. The
// dedicated LaxiiJob table this module's routes were written against no
// longer exists; these functions expose the SAME shapes the routes and the
// studio expect, backed by the live store. Nothing is faked: status,
// stage, errors and results are read from real rows.
// ---------------------------------------------------------------------------

export const MAX_VARIATIONS = 4;

/** Old-route job shape (routes serialize these fields verbatim). */
export interface LaxiiJobRowView {
  id: string;
  kind: string;
  provider: string;
  style: string | null;
  status: "QUEUED" | "RUNNING" | "SUCCEEDED" | "FAILED" | "CANCELLED";
  stage: string | null;
  progress: number;
  paramsJson: string;
  resultsJson: string;
  error: string | null;
  attempt: number;
  createdAt: Date;
  completedAt: Date | null;
}

type JobMessageRow = {
  id: string;
  operation: string | null;
  provider: string | null;
  model: string | null;
  status: string;
  error: string | null;
  metaJson: string | null;
  createdAt: Date;
  versions: { mediaId: string; createdAt: Date }[];
};

function jobStatusOf(row: { status: string }): LaxiiJobRowView["status"] {
  if (row.status === "DONE") return "SUCCEEDED";
  if (row.status === "FAILED") return "FAILED";
  return "RUNNING";
}

function toJobView(row: JobMessageRow): LaxiiJobRowView {
  const meta = row.metaJson ? (safeParseRecord(row.metaJson) ?? {}) : {};
  const status = jobStatusOf(row);
  // LaxiiMessage has no updatedAt column; the newest version row is the real
  // completion timestamp when one exists (RUNNING jobs complete to null).
  const lastVersionAt = row.versions.reduce<Date | null>(
    (acc, v) => (!acc || v.createdAt > acc ? v.createdAt : acc),
    null
  );
  return {
    id: row.id,
    kind: row.operation ?? "GENERATE",
    provider: row.provider ?? "auto",
    style: (meta.style as string | undefined) ?? null,
    status,
    stage: (meta.stage as string | undefined) ?? null,
    progress: status === "SUCCEEDED" ? 100 : 0,
    paramsJson: JSON.stringify({ aspect: meta.aspect ?? null, refs: meta.refs ?? [], banner: meta.banner ?? null, style: meta.style ?? null }),
    resultsJson: JSON.stringify(row.versions.map((v) => ({ mediaAssetId: v.mediaId }))),
    error: row.error,
    attempt: 1, // the current pipeline is single-attempt per message (retry creates a new job)
    createdAt: row.createdAt,
    completedAt: status === "RUNNING" ? null : (lastVersionAt ?? row.createdAt),
  };
}

function safeParseRecord(json: string): Record<string, unknown> | null {
  try {
    const parsed = JSON.parse(json);
    return parsed && typeof parsed === "object" ? (parsed as Record<string, unknown>) : null;
  } catch {
    return null;
  }
}

/** Recent jobs across the user's conversations, newest first. */
export async function listJobs(userId: string, limit = 12): Promise<LaxiiJobRowView[]> {
  const rows = await db.laxiiMessage.findMany({
    where: { role: "ASSISTANT", conversation: { userId } },
    orderBy: { createdAt: "desc" },
    take: Math.min(Math.max(1, limit), 60),
    include: { versions: { select: { mediaId: true, createdAt: true }, orderBy: { createdAt: "asc" } } },
  });
  return rows.map(toJobView);
}

/** One job (owner-only; foreign ids are indistinguishable from missing). */
export async function getJob(userId: string, id: string): Promise<LaxiiJobRowView | null> {
  const row = await db.laxiiMessage.findFirst({
    where: { id, role: "ASSISTANT", conversation: { userId } },
    include: { versions: { select: { mediaId: true, createdAt: true }, orderBy: { createdAt: "asc" } } },
  });
  return row ? toJobView(row) : null;
}

/**
 * Re-run a FAILED job. The current pipeline cannot resume an old message
 * (the exact spec is not fully recoverable), so a retry starts a NEW turn in
 * the same conversation with the best recoverable parameters (prompt,
 * operation, refs, banner canvas) — the honest, working path; the response
 * carries the new job id.
 */
export async function retryJob(userId: string, id: string): Promise<LaxiiJobRowView | null> {
  const { startGenerationJob } = await import("./jobs");
  const original = await db.laxiiMessage.findFirst({
    where: { id, role: "ASSISTANT", conversation: { userId } },
    include: { conversation: { select: { id: true, kind: true, canvasWidth: true, canvasHeight: true, bannerKind: true } }, versions: true },
  });
  if (!original) return null;
  if (original.status !== "FAILED") {
    throw new LaxiiError("Only failed generations can be retried");
  }
  const meta = original.metaJson ? (safeParseRecord(original.metaJson) ?? {}) : {};
  const prompt =
    original.versions.find((v) => v.prompt)?.prompt ??
    (await db.laxiiMessage.findFirst({
      where: { conversationId: original.conversationId, role: "USER", createdAt: { lt: original.createdAt } },
      orderBy: { createdAt: "desc" },
      select: { text: true },
    }))?.text ??
    "";
  if (!prompt.trim()) throw new LaxiiError("The original prompt for this job could not be recovered — start a new generation");

  const operation = String(original.operation ?? "GENERATE");
  const isEditLike = ["EDIT", "VARIATIONS", "REMOVE_BG", "OUTPAINT", "UPSCALE"].includes(operation);
  const referenceIds = Array.isArray(meta.refs) ? (meta.refs as string[]).slice(0, 10) : [];
  const { messageId } = await startGenerationJob({
    userId,
    conversationId: original.conversationId,
    requestOperation: operation as Parameters<typeof startGenerationJob>[0]["requestOperation"],
    engineOperation: (operation === "BANNER" ? "GENERATE" : operation === "REMOVE_BG" ? "REMOVE_BACKGROUND" : operation === "OUTPAINT" ? "EXPAND" : operation) as Parameters<typeof startGenerationJob>[0]["engineOperation"],
    userText: prompt,
    promptFinal: prompt,
    references: referenceIds.length ? await loadOwnedMediaAsReferences(userId, isEditLike ? referenceIds.slice(0, 1) : referenceIds.slice(0, 3)) : [],
    baseImage: isEditLike && referenceIds[0] ? (await loadOwnedMediaAsReferences(userId, [referenceIds[0]]))[0] : undefined,
    aspect: "1:1",
    count: 1,
    provider: undefined,
    quality: "1K",
    bannerCanvas:
      original.conversation.kind === "BANNER" && original.conversation.canvasWidth && original.conversation.canvasHeight
        ? { width: original.conversation.canvasWidth, height: original.conversation.canvasHeight, presetSlug: original.conversation.bannerKind ?? "bean-folio-banner" }
        : null,
    extraWarnings: ["Retried from an earlier failed generation — some original settings may differ."],
    parentVersionId: null,
    referenceMediaIds: referenceIds,
    intentKind: null,
    intentSource: null,
    styleSlug: (meta.style as string | undefined) ?? null,
    previousInteractionId: null,
    conversationContext: null,
    inputAssetIds: referenceIds,
    briefTaskId: null,
    brief: null,
    promptBriefBase: null,
  });
  return getJob(userId, messageId);
}

/**
 * Cancel a RUNNING job. The current worker is not interruptible mid-call, so
 * the job is marked FAILED honestly — if the engine still completes in the
 * background its outputs surface in the thread as saved versions.
 */
export async function cancelJob(userId: string, id: string): Promise<LaxiiJobRowView | null> {
  const row = await db.laxiiMessage.findFirst({
    where: { id, role: "ASSISTANT", conversation: { userId } },
    include: { versions: { select: { mediaId: true, createdAt: true }, orderBy: { createdAt: "asc" } } },
  });
  if (!row) return null;
  if (row.status === "DONE") throw new LaxiiError("A finished generation cannot be cancelled — its results belong to you");
  if (row.status !== "RUNNING") throw new LaxiiError(`This job is ${row.status.toLowerCase()} and cannot be cancelled`);
  const updated = await db.laxiiMessage.update({
    where: { id: row.id },
    data: { status: "FAILED", error: "Cancelled by the user — the engine may still finish in the background; its result would appear in the thread." },
  });
  return toJobView({ ...updated, versions: row.versions });
}

/**
 * Direct job creation (POST /api/laxii/jobs) is not part of the current
 * pipeline — jobs are started from conversations (/api/laxii/generate, the
 * studio composer) so lineage and canvas handling stay in one place. The
 * binding is kept so legacy imports resolve; it fails HONESTLY.
 */
export async function createJob(_userId: string, _input: unknown): Promise<LaxiiJobRowView> {
  void _userId;
  void _input;
  throw new LaxiiError("Direct job creation moved into the studio flow — use POST /api/laxii/generate or the studio composer");
}
